import math
def control(obs):
    m=obs['local_map']
    def interp(points,x):
        pts=sorted(points)
        for i in range(len(pts)-1):
            a,b=pts[i],pts[i+1]
            if a[0]<=x<=b[0] and b[0]-a[0]>0.01:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return None
    vals=[]
    for x in (3.0,4.0,5.0):
        l=interp(m['left_rail'],x); r=interp(m['right_rail'],x)
        if l is not None and r is not None: vals.append((l+r)/2)
    err=sum(vals)/len(vals) if vals else 0
    desired=max(-18,min(18,err*8))
    h=obs['hitch_deg']
    steer=max(-34,min(34,2.2*(h-desired)))
    return steer,-0.8

