import math
def interp(points, x):
    p=sorted(points)
    for (a,b),(c,d) in zip(p,p[1:]):
        if a <= x <= c and c-a > 0.05: return b+(d-b)*(x-a)/(c-a)
    return None
def control(obs):
    m=obs['local_map']; l=m['left_rail']; r=m['right_rail']
    centers=[]
    for x in (3.0,5.0,7.0,9.0):
        a=interp(l,x); b=interp(r,x)
        if a is not None and b is not None: centers.append((x,(a+b)/2))
    if centers:
        x,y=centers[min(2,len(centers)-1)]
        desired=max(-18,min(18,math.degrees(math.atan2(y,x))*1.1))
    else: desired=0
    h=obs['hitch_deg']
    steer=max(-40,min(40, 2.0*(h-desired)))
    return (steer,-0.8)

