import math
def control(obs):
    left=obs['local_map']['left_rail']; right=obs['local_map']['right_rail']
    def at(points,u):
        pts=sorted(points)
        for i in range(len(pts)-1):
            a,b=pts[i],pts[i+1]
            if a[0]<=u<=b[0] and b[0]-a[0]>0.001:
                return a[1]+(b[1]-a[1])*(u-a[0])/(b[0]-a[0])
        return min(pts,key=lambda p:abs(p[0]-u))[1] if pts else 0
    c1=(at(left,1.0)+at(right,1.0))/2
    c2=(at(left,2.3)+at(right,2.3))/2
    desired=max(-22,min(22,-14*c1-12*(c2-c1)))
    hitch=obs['hitch_deg']
    steer=max(-40,min(40,2.0*(hitch-desired)))
    return (steer,-0.45,180)

